import lineStopsJson from "../data/line-stops.json";
import { stops, StopsEntry } from "./stops";

/**
 * Metrolink lines, with their stops in order. Generated by `npm run gtfs-line-stops` (see data/lines/README.md).
 *
 * Lines are labelled by their service, e.g. "Altrincham – Bury", which is how people know them. The colour names
 * ("Green Line") are TfGM's, but they've only been used recently and have changed what they cover, so they're shown
 * as a secondary, visual aid.
 */
type LineStopsJson = Record<string, { service: string | null; stops: string[]; links: string[][] }>;

export type Line = {
  /** TfGM's line id, e.g. "Green Line" */
  id: string;
  /** e.g. "Altrincham – Bury" */
  name: string;
  /** e.g. "Green" */
  colourName: string;
  /** A CSS colour, for the swatch next to the line's name and its route */
  colour: string;
  /** Whether the colour is too dark to show on dark mode's panels by itself, so needs an outline there */
  outlineOnDark: boolean;
  /** In order from the first stop in the name to the second. Branches are slotted in next to where they join */
  stops: StopsEntry[];
  /** Pairs of stops trams run directly between, in the same direction as `stops` */
  links: [StopsEntry, StopsEntry][];
};

/** Lines with a colour defined in index.css, as --line-blue etc. TfGM's own colours */
const coloursDefined = new Set(["Blue", "Green", "Navy", "Pink", "Purple", "Red", "Yellow"]);

/** Colours under 3:1 contrast against dark mode's panels (gray-800): Navy 2.5:1, Purple 1.6:1 */
const darkColours = new Set(["Navy", "Purple"]);

const stopsByAtco = new Map(stops.map((stop) => [stop.atcoCode, stop]));

export const lines: Line[] = Object.entries(lineStopsJson as LineStopsJson)
  .map(([id, line]): Line => {
    const lineStops = line.stops.flatMap((atcoCode) => stopsByAtco.get(atcoCode) ?? []);
    const links = line.links.flatMap(([from, to]): [StopsEntry, StopsEntry][] => {
      const [fromStop, toStop] = [stopsByAtco.get(from), stopsByAtco.get(to)];
      return fromStop && toStop ? [[fromStop, toStop]] : [];
    });

    const colourName = id.replace(/ Line$/, "");

    return {
      id,
      name: line.service?.replace(" - ", " – ") ?? id,
      colourName,
      colour: coloursDefined.has(colourName) ? `var(--line-${colourName.toLowerCase()})` : "currentColor",
      outlineOnDark: darkColours.has(colourName),
      stops: lineStops,
      links,
    };
  })
  .sort((a, b) => a.name.localeCompare(b.name));

/** Lines serving a stop */
export function linesAtStop(atcoCode: string): Line[] {
  return lines.filter(({ stops }) => stops.some((stop) => stop.atcoCode === atcoCode));
}

/** A line's first and last stops, e.g. Altrincham and Bury */
export function lineEnds(line: Line): [StopsEntry, StopsEntry] {
  return [line.stops[0], line.stops[line.stops.length - 1]];
}

/**
 * The stops either side of a stop on a line: towards the line's first stop, and towards its last. Usually one each
 * way, none at the end of the line, or more than one where the line branches.
 */
export function neighbours(line: Line, atcoCode: string): { towardsStart: StopsEntry[]; towardsEnd: StopsEntry[] } {
  return {
    towardsStart: line.links.filter(([, to]) => to.atcoCode === atcoCode).map(([from]) => from),
    towardsEnd: line.links.filter(([from]) => from.atcoCode === atcoCode).map(([, to]) => to),
  };
}
